application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #526078;
  --line: #c8d1df;
  --surface: #ffffff;
  --background: #f3f6fb;
  --accent: #2457a6;
  --accent-dark: #173e7a;
  --error: #a32828;
}

body {
  margin: 0;
  min-width: 18rem;
  background: var(--background);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

.quiz-shell {
  width: min(100% - 2rem, 48rem);
  margin: 0 auto;
  padding: 2.5rem 0;
}

.quiz-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: var(--accent-dark);
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .09em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(1.8rem, 5vw, 2.5rem);
  line-height: 1.15;
}

.quiz-header p:last-child {
  margin-bottom: 0;
  color: var(--muted);
}

.questions {
  display: grid;
  gap: 1rem;
}

.question {
  min-inline-size: 0;
  margin: 0;
  padding: 1.25rem;
  border: 1px solid var(--line);
  border-radius: .75rem;
  background: var(--surface);
}

legend {
  max-width: 100%;
  padding: 0 .25rem;
  font-weight: 700;
}

.question-number {
  color: var(--accent-dark);
}

.options {
  display: grid;
  gap: .65rem;
  margin-top: 1rem;
}

.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  padding: .7rem .8rem;
  border: 1px solid var(--line);
  border-radius: .45rem;
  cursor: pointer;
}

.option:hover {
  border-color: var(--accent);
  background: #f4f7fd;
}

.option input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--accent);
}

.option:has(input:checked) {
  border-color: var(--accent);
  background: #eaf1ff;
}

button {
  font: inherit;
}

.submit-button {
  margin-top: 1.5rem;
  padding: .75rem 1.2rem;
  border: 0;
  border-radius: .45rem;
  background: var(--accent);
  color: white;
  font-weight: 700;
  cursor: pointer;
}

.submit-button:hover {
  background: var(--accent-dark);
}

:focus-visible {
  outline: 3px solid #f0a900;
  outline-offset: 3px;
}

.form-error {
  margin: 1rem 0 0;
  color: var(--error);
  font-weight: 700;
}

.result {
  margin-top: 2rem;
  padding: 1.25rem;
  border-left: .35rem solid var(--accent);
  background: var(--surface);
}

.result h2 {
  margin-bottom: .35rem;
  font-size: 1.15rem;
}

.score-message {
  margin-bottom: 0;
  color: var(--muted);
}

@media (max-width:  thirtyrem) {
  .quiz-shell {
    padding: 1.5rem 0;
  }
}

application.javascript:
const form = document.querySelector('#quiz-form');
const errorMessage = document.querySelector('#form-error');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');

const correctAnswers = Object.freeze({
  'question-1': 'mars',
  'question-2': 'pacific',
  'question-3': 'css'
});

function getAnsweredCount() {
  return Object.keys(correctAnswers).filter((name) => {
    return form.querySelector(`input[name="${name}"]:checked`) !== null;
  }).length;
}

function calculateScore() {
  return Object.entries(correctAnswers).reduce((score, [name, answer]) => {
    const selected = form.querySelector(`input[name="${name}"]:checked`);
    return score + (selected && selected.value === answer ? 1 : 0);
  }, 0);
}

function showScore(score) {
  scoreElement.dataset.score = String(score);
  scoreElement.textContent = `Your score is ${score} out of 3.`;
}

function handleSubmit(event) {
  event.preventDefault();
  const answeredCount = getAnsweredCount();

  if (answeredCount !== 3) {
    errorMessage.hidden = false;
    errorMessage.textContent = `Please answer all three questions. ${3 - answeredCount} question${3 - answeredCount === 1 ? '' : 's'} remain.`;
    const firstUnanswered = [...form.querySelectorAll('fieldset')].find((fieldset) => {
      return !fieldset.querySelector('input:checked');
    });
    firstUnanswered?.querySelector('input')?.focus();
    return;
  }

  errorMessage.hidden = true;
  showScore(calculateScore());
}

function clearError() {
  errorMessage.hidden = true;
}

form.addEventListener('submit', handleSubmit);
form.addEventListener('change', clearError);
